"""Pre-result source packaging. Authoring only; not imported by execution."""
from pathlib import Path
import json, hashlib, random, re
P=Path(__file__).parent

def sha(b):return hashlib.sha256(b).hexdigest()
def dump(path,v):
 path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
def oid(x):return 'q-'+sha(('arena-20260913-packet-salt-6c92/'+x).encode())[:16]
DICTIONARY='''Choose one label for the supplied claim relative to the supplied evidence packet.
solid: Claims accurately report the evidence with appropriate scope and caveats. Weak, observational, preclinical or mixed evidence can be reported accurately.
overclaim: The conclusion exceeds the evidence. This is the residual category for inflated framing, unsupported positive or negative generalization, extrapolation to unstudied populations, and surrogate endpoints presented as clinical outcomes.
correlation_vs_causation: A causal claim is drawn from a non-causal, uncontrolled or confounded design; correlation is treated as causation without the needed counterfactual/comparison.
mechanism_vs_evidence: A described biological mechanism (an animal or preclinical pathway) is used to imply human clinical benefit not demonstrated by the evidence. This includes animal-to-human therapeutic and preclinical-pathway-to-therapeutic leaps. A biomarker/surrogate-to-clinical gap alone is excluded from this category.
Precedence: A specific label (correlation_vs_causation or mechanism_vs_evidence) takes precedence over generic overclaim only when its defining trigger is present and captures the core error. Do not stretch a specific definition; otherwise use overclaim. If the claim is appropriately bounded by the evidence, use solid.'''
# These are original paraphrases of the retrieved primary abstracts, not candidate preparation instructions.
PACKETS={
1:'STEP 1 was a double-blind randomized trial in 1,961 adults without diabetes, with BMI at least 30, or at least 27 plus a weight-related condition. Participants received weekly subcutaneous semaglutide 2.4 mg or placebo (2:1), with lifestyle intervention in both groups, for 68 weeks. Mean body-weight change was -14.9% versus -2.4%; the estimated difference was -12.4 percentage points (95% CI -13.4 to -11.5).',
2:'In a prospective observational Greek cohort, 22,043 adults completed food-frequency questionnaires. Adherence to a traditional Mediterranean diet was scored from 0 to 9. Median follow-up was 44 months, during which 275 deaths occurred. After adjustment for age, sex and other measured factors, each two-point increase in score was associated with an all-cause mortality hazard ratio of 0.75 (95% CI 0.64 to 0.87). Dietary intake was measured, not experimentally assigned.',
3:'In the final RECOVERY report, hospitalized COVID-19 patients were randomized open-label to dexamethasone 6 mg daily for up to 10 days (2,104 patients) or usual care (4,321). Overall 28-day mortality was 22.9% versus 25.7%, age-adjusted rate ratio 0.83 (95% CI 0.75 to 0.93). At randomization, invasively ventilated patients had mortality 29.3% versus 41.4%, rate ratio 0.64 (0.51 to 0.81); patients on oxygen without invasive ventilation had 23.3% versus 26.2%, rate ratio 0.82 (0.72 to 0.94); patients receiving no respiratory support had 17.8% versus 14.0%, rate ratio 1.19 (0.92 to 1.55).',
4:'DAPA-HF randomized 4,744 patients with NYHA class II-IV heart failure and left ventricular ejection fraction at most 40% to dapagliflozin 10 mg daily or placebo in addition to recommended care. Over median 18.2 months, the primary composite of worsening heart failure (hospitalization or urgent visit requiring intravenous therapy) or cardiovascular death occurred in 386/2,373 (16.3%) versus 502/2,371 (21.2%), hazard ratio 0.74 (95% CI 0.65 to 0.85).',
5:'The DASH feeding trial enrolled 459 adults with systolic blood pressure below 160 mm Hg and diastolic pressure 80-95 mm Hg. After three weeks on a control diet, they were randomly assigned to eight weeks of the control diet, a fruit-and-vegetable diet, or a combination diet rich in fruit, vegetables and low-fat dairy with reduced saturated and total fat. Sodium intake and body weight were maintained constant. The combination diet reduced mean systolic and diastolic pressure by 5.5 and 3.0 mm Hg more than control, respectively.',
6:'Mouse experiments tested nicotinamide riboside (NR), a precursor that replenishes NAD+. NR induced the mitochondrial unfolded protein response and synthesis of prohibitin proteins and improved the function of aged muscle stem cells. It also prevented muscle stem-cell senescence in the mdx muscular dystrophy mouse model. Separate experiments reported delayed senescence of neural and melanocyte stem cells and increased mouse lifespan. The reported organism-level outcomes are in mice.',
7:'SELECT was a double-blind randomized trial of weekly semaglutide 2.4 mg versus placebo in 17,604 adults aged at least 45 with BMI at least 27, established cardiovascular disease, and no history of diabetes. Mean follow-up was 39.8 months. The composite of cardiovascular death, nonfatal myocardial infarction or nonfatal stroke occurred in 569/8,803 (6.5%) versus 701/8,801 (8.0%), hazard ratio 0.80 (95% CI 0.72 to 0.90).',
8:'VITAL randomized 25,871 US men aged at least 50 and women aged at least 55 in a placebo-controlled factorial trial that included vitamin D3 2,000 IU daily. Median follow-up was 5.3 years. Vitamin D versus placebo gave an invasive cancer hazard ratio of 0.96 (95% CI 0.88 to 1.06; P=0.47) and a major cardiovascular event hazard ratio of 0.97 (0.85 to 1.12; P=0.69). The trial did not find statistically significant reductions in these primary outcomes.',
9:'CRASH-2 randomized 20,211 adult trauma patients with, or at risk of, significant bleeding within eight hours of injury to tranexamic acid (1 g over 10 minutes followed by 1 g over eight hours) or placebo. Allocation was masked. The primary outcome was death in hospital within four weeks. All-cause mortality was 14.5% with tranexamic acid and 16.0% with placebo, relative risk 0.91 (95% CI 0.85 to 0.97). This packet covers the original randomized report.',
10:'KEYNOTE-024 randomized 305 previously untreated patients with advanced non-small-cell lung cancer, PD-L1 expression on at least 50% of tumor cells, and no sensitizing EGFR mutation or ALK translocation, to pembrolizumab 200 mg every three weeks or platinum-based chemotherapy. Median progression-free survival was 10.3 versus 6.0 months, hazard ratio 0.50 (95% CI 0.37 to 0.68). Estimated six-month overall survival was 80.2% versus 72.4%, hazard ratio for death 0.60 (0.41 to 0.89).',
11:'ATTIRE randomized 777 hospitalized patients with decompensated cirrhosis and serum albumin below 30 g/L to repeated 20% albumin infusions targeting at least 30 g/L or standard care for up to 14 days. The composite of new infection, kidney dysfunction or death on days 3-15 occurred in 113/380 (29.7%) versus 120/397 (30.2%); adjusted odds ratio 0.98 (95% CI 0.71 to 1.33; P=0.87). More severe or life-threatening serious adverse events occurred in the albumin group.',
12:'TEAM-AD was a randomized placebo-controlled trial at 14 Veterans Affairs centers in 613 patients with established mild-to-moderate Alzheimer disease already receiving an acetylcholinesterase inhibitor. The arms were alpha tocopherol 2,000 IU daily, memantine 20 mg daily, their combination, and placebo. Over mean follow-up 2.27 years, the alpha-tocopherol group had 3.15 points less decline on the ADCS-ADL daily-function scale than placebo (95% CI 0.92 to 5.39; adjusted P=0.03). Memantine and the combination did not show this benefit. An online correction updated one table value and figure/supplement values; this packet uses the indexed corrected abstract and does not use those table/figure values.',
13:'In 2014, a nationally representative US sample of 1,788 adults aged 19-32 completed self-report measures of daily social media minutes, weekly visits, and PROMIS sleep disturbance. This was a cross-sectional survey. Adjusted for measured sociodemographic covariates, the highest versus lowest quartile of daily use had an adjusted odds ratio of 1.95 (95% CI 1.37 to 2.79) for sleep disturbance; the corresponding weekly frequency estimate was 2.92 (1.97 to 4.32).',
14:'This observational analysis followed 76,464 women in the Nurses\' Health Study and 42,498 men in the Health Professionals Follow-up Study, excluding people with histories of cancer, heart disease or stroke. Nut intake was assessed by questionnaires at baseline and every two to four years. During 3,038,853 person-years, 27,429 deaths occurred. After multivariable adjustment, consumption seven or more times weekly versus never was associated with total mortality hazard ratio 0.80 (95% CI 0.73 to 0.86).',
15:'A prospective observational NutriNet-Sante analysis included 44,551 French adults aged at least 45 who supplied at least three 24-hour dietary records. Ultra-processed food intake was expressed as a proportion of total food weight. During median follow-up 7.1 years, 602 deaths occurred. After adjustment for measured demographic, lifestyle and diet factors, each ten-percentage-point higher proportion was associated with mortality hazard ratio 1.14 (95% CI 1.04 to 1.27).',
16:'The All Our Families cohort analysis used data from 2,441 mothers and children in Calgary, Canada, at child ages 24, 36 and 60 months. Mothers reported screen time and ASQ-3 developmental screening performance. A random-intercepts cross-lagged panel model controlled stable between-person differences. Higher screen time at 24 months was associated with lower screening performance at 36 months (standardized beta -0.06, 95% CI -0.10 to -0.01); higher screen time at 36 months was associated with lower performance at 60 months (-0.08, -0.13 to -0.02). Exposure was observed. This uses corrected estimates: the 2019 correction clarified the model and corrected/swapped displayed coefficients and confidence intervals without changing the conclusions.',
17:'The Sister Study paper includes a baseline and prospective observational analysis of 43,722 US and Puerto Rican women aged 35-74. Women with a history of cancer or cardiovascular disease, shift workers, daytime sleepers and women pregnant at baseline were excluded. Artificial light during sleep was self-reported as none, a small nightlight, light outside the room, or light/television in the room. This packet uses the baseline association: any artificial light versus none was associated with a higher prevalence of BMI-defined obesity (BMI at least 30), adjusted prevalence ratio 1.03 (95% CI 1.02 to 1.03). Baseline anthropometric measurements were taken; lighting was observed, not assigned.',
18:'An observational analysis of England covered approximately 40.8 million residents below retirement age and 366,348 individual death records during 2001-2005. Residential green-space exposure and income deprivation were linked to mortality data and analyzed in adjusted strata. The all-cause mortality incidence rate ratio comparing most versus least deprived groups was 1.93 (95% CI 1.86 to 2.01) in the least-green areas and 1.43 (1.34 to 1.53) in the greenest. Similar patterns occurred for circulatory mortality, but not lung cancer or suicide. Neighborhood greenery was observed, not assigned.',
19:'Researchers delivered Cas9-guide RNA complexes into the cochlea of neonatal Beethoven mice carrying a dominant Tmc1 deafness allele. The editing agents preferentially disrupted the mutant allele, which differed from wild type by one base pair. Compared with uninjected ears or control complexes targeting an unrelated gene, treated ears showed greater hair-cell survival and lower auditory brainstem response thresholds; injected mice also had enhanced acoustic startle responses. The intervention reduced progressive hearing loss in this mouse model.',
20:'Researchers used adeno-associated virus to deliver CRISPR-Cas9 in the mdx mouse model of Duchenne muscular dystrophy, removing mutant exon 23 from the dystrophin gene. Delivery was local or systemic in adult mice and systemic in neonatal mice. Exon deletion produced modified dystrophin expression, partial restoration of functional dystrophin in skeletal and cardiac muscle, improved muscle biochemistry and increased muscle force. The experiments described in this report are in mice.',
21:'In adult rats with lesioned spinal dorsal columns, researchers delivered chondroitinase ABC intrathecally. The enzyme degraded chondroitin-sulfate glycosaminoglycan chains at the injury site, reducing the inhibitory action of scar-associated proteoglycans on axon growth. The study reported regeneration of ascending sensory and descending corticospinal axons, restored postsynaptic activity below the lesion after electrical stimulation, and improved locomotor and proprioceptive behavior in treated rats.',
22:'CD47 binds SIRP-alpha on phagocytic cells and provides a signal that inhibits engulfment. Experiments with human tumor cells showed that anti-CD47 antibodies enabled macrophage phagocytosis in vitro. In immunodeficient mice carrying patient-derived tumor xenografts, antibody administration inhibited tumor growth and increased mouse survival; an immunocompetent mouse breast-tumor model was also studied. Human patient tumor tissue was used for expression measurements and to establish xenografts; the report describes antibody treatment outcomes in mice.',
23:'Researchers used an adeno-associated viral vector to express channelrhodopsin-2, a microbial light-sensitive ion channel, in surviving inner retinal neurons of rodents. In a mouse model with photoreceptor degeneration, this conferred light responsiveness on these cells and restored retinal encoding of light signals and their transmission to the visual cortex. The experiments evaluated rodent retinal and cortical responses following loss of rods and cones.',
24:'MCC950 inhibited canonical and noncanonical activation of the NLRP3 inflammasome at nanomolar concentrations, without inhibiting AIM2, NLRC4 or NLRP1 inflammasomes. It reduced IL-1 beta production in vivo and attenuated experimental autoimmune encephalomyelitis, a mouse model of multiple sclerosis. It also rescued neonatal lethality in a mouse model of cryopyrin-associated periodic syndrome and showed activity in ex vivo samples from people with Muckle-Wells syndrome. The reported human samples were treated outside the body.'}
REPLACEMENTS={17:('The retired P7A-BND-003 grip-strength case uses the same underlying PURE cohort; exclude shared historical participants conservatively.','The Sister Study analysis establishes that eliminating artificial light while sleeping prevents obesity in women.'),13:('Historical coffee mortality claim family (case046) overlaps.','The social media survey establishes that reducing social media use would cause less sleep disturbance in young adults.'),19:('Prior resveratrol/sirtuin human-longevity intake family overlaps.','By selectively disrupting the mutant Tmc1 allele and preserving hair cells, this study establishes that cochlear CRISPR treatment prevents progressive hearing loss in human patients with inherited deafness.'),20:('Prior dasatinib-quercetin aging/physical-function claim family overlaps.','Restoring dystrophin through CRISPR removal of the defective exon establishes that this treatment improves muscle strength in patients with Duchenne muscular dystrophy.'),21:('Prior metformin human-longevity claim family overlaps.','Because chondroitinase ABC removes scar-associated inhibition of axon growth, these experiments establish that it restores mobility in people with spinal cord injuries.'),22:('Prior spermidine/autophagy human-longevity claim family overlaps.','Blocking the CD47 signal lets macrophages engulf tumor cells; these experiments establish that anti-CD47 treatment improves survival in human patients with solid tumors.'),23:('Original curcumin paper has an erratum whose decisive body could not be verified; a retrieved page contained a different paper.','By making surviving retinal neurons light-sensitive with channelrhodopsin-2, these experiments establish that this treatment restores vision in people who have lost their photoreceptors.'),24:('Prior EGCG cancer-prevention claim intake overlaps.','Because MCC950 blocks the NLRP3 inflammatory pathway, these experiments establish that MCC950 treats multiple sclerosis in human patients.')}

def main():
 b=json.loads((P/'candidate_authoring/candidate_bank.json').read_text()); inputs=[];oracle=[];sources=[];decisions=[]
 for i,c in enumerate(b['candidates'],1):
  cid=c['candidate_id']; rid='R'+cid[1:] if i in REPLACEMENTS else cid
  fetched=json.loads((P/f'candidate_authoring/source_retrieval/{rid}.json').read_text());h=next(x for x in fetched['hits'] if x.get('source')=='MED' and (i!=9 or x['id']=='20554319'))
  assert h.get('abstractText') and h.get('doi')
  abstract=re.sub('<[^>]*>',' ',h['abstractText'])
  source={'title':h['title'],'doi':h['doi'],'url':f'https://pubmed.ncbi.nlm.nih.gov/{h["id"]}/','locator':'Primary article abstract; corrected online abstract where applicable','version':h.get('firstPublicationDate'),'retrieval_date':fetched['retrieved_at'],'retrieval_url':fetched['url'],'retrieval_body_sha256':fetched['body_sha256'],'abstract_text_sha256':sha(abstract.encode()),'publication_types':h.get('pubTypeList'),'linked_notices':h.get('commentCorrectionList'),'status_check':'Primary indexed record checked for linked corrections/retraction; no indexed retraction flag identified.'}
  if i==12:source['correction']={'doi':'10.1001/jama.2014.641','url':'https://jamanetwork.com/journals/JAMA/articlepdf/1841950/jcx140005.pdf','disposition':'Table2 and figure/supplement values corrected. Packet uses abstract population and ADCS-ADL estimate, not the affected displays.'}
  if i==16:source['correction']={'doi':'10.1001/jamapediatrics.2019.0515','url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC6503492/','disposition':'Corrected beta ordering, figure intervals and model text used.'}
  claim=REPLACEMENTS[i][1] if i in REPLACEMENTS else c['authored_claim']
  packet={'source':{k:source[k] for k in ['title','doi','url','version']},'evidence':PACKETS[i]}
  source['version']='Indexed primary abstract body sha256:'+source['abstract_text_sha256']+'; publication '+str(source['version'])+('; final RECOVERY NEJM 2021;384:693-704, PMID 32678530' if i==3 else '')+('; online corrected version, correction '+source['correction']['doi'] if i in (12,16) else '')
  packet['source']['version']=source['version']
  source['packet_sha256']=sha(json.dumps(packet,sort_keys=True,ensure_ascii=False).encode());source['authoring_id']=cid;sources.append(source)
  inp={'id':oid(cid),'claim':claim,'packet':packet};inputs.append(inp)
  rationale=c['oracle_rationale'] if i not in REPLACEMENTS else ('A causal intervention effect is asserted from a cross-sectional observational association.' if i in (13,17) else 'A documented preclinical biological mechanism is used to establish human clinical benefit; the supplied study did not treat human participants for that clinical outcome.')
  oracle.append({'id':inp['id'],'root_id':oid(cid),'role':'primary','authoring_id':cid,'gold':c['provisional_gold'],'rationale':rationale,'source_packet_sha256':source['packet_sha256'],'independence':'Distinct underlying study and claim family after local overlap screening; foundation pretraining exposure UNKNOWN','adjudication':'AUTHOR_RECHECK_PENDING_BLIND_REVIEW'})
  decisions.append({'authoring_id':cid,'action':'REPLACE' if i in REPLACEMENTS else 'RETAIN','reason':REPLACEMENTS[i][0] if i in REPLACEMENTS else 'Source body supports a decisive scoped packet. No same study/claim family identified in local historical corpus.','original_doi':c['doi'],'adopted_doi':h['doi'],'claim_edit':'Replacement source requires replacement claim' if i in REPLACEMENTS else None})
 for v in b['variants']:
  cid=v['root_candidate_id'];base=next(x for x in inputs if x['id']==oid(cid));claim=v['authored_claim']
  if cid=='C21':claim='The experiments establish restored mobility in human spinal-cord-injury patients through chondroitinase ABC removal of the scar molecules that inhibit axon growth.'
  if cid=='C22':claim='These experiments establish longer survival for solid-tumor patients by using anti-CD47 antibodies to remove the signal that protects tumor cells from macrophages.'
  inputs.append({'id':oid(v['variant_id']),'claim':claim,'packet':base['packet']})
  o=next(x for x in oracle if x['id']==oid(cid));oracle.append({**o,'id':oid(v['variant_id']),'role':'variant','authoring_id':v['variant_id'],'equivalence':'Same intervention/exposure, scope, clinical conclusion and certainty; AUTHOR_RECHECK_PENDING_BLIND_REVIEW'})
 random.Random(20260913).shuffle(inputs)
 dump(P/'fresh_holdout_input/inputs.json',inputs);dump(P/'fresh_holdout_oracle/oracle.json',oracle)
 dump(P/'candidate_authoring/sources.json',sources);dump(P/'candidate_authoring/replacement_log.json',decisions)
 (P/'common_dictionary.txt').write_text(DICTIONARY+'\n')
 # Reviewer sees only shuffled cases, source packets, source identities/status and canonical definitions.
 reviewdir=Path('/tmp/arena-blind-source-review-20260913');reviewdir.mkdir(exist_ok=True)
 dump(reviewdir/'cases.json',inputs);(reviewdir/'definitions.txt').write_text(DICTIONARY+'\n')
 dump(reviewdir/'source_status.json',[{k:v for k,v in s.items() if k!='authoring_id'} for s in sources])
 print('Packaged',len(inputs),'stimuli;',len(REPLACEMENTS),'replacements; reviewer folder',reviewdir)
if __name__=='__main__':main()
